/// <reference path="../edge-runtime.d.ts" />
import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { encryptTikTokContentToken } from "../_shared/tiktokContentConfigCrypto.ts";
import {
  mergeTikTokContentOAuthScopes,
  TIKTOK_CONTENT_OAUTH_SCOPES,
  TIKTOK_CONTENT_PUBLISH_OAUTH_SCOPES,
  TIKTOK_CONTENT_OAUTH_RETURN_PATHS,
  TIKTOK_CONTENT_OAUTH_TOKEN_KINDS,
  appPublicOrigin,
  readPlatformTikTokContentOAuth,
  readPlatformTikTokContentPublishOAuth,
  tiktokContentOAuthRedirectUri,
} from "../_shared/tiktokContentAuth.ts";
import { exchangeTikTokBusinessOrganicAuthCode, exchangeTikTokContentAuthCode, fetchTikTokUserInfo } from "../_shared/tiktokContentApi.ts";
import { isPlaceholderTikTokAccountLabel } from "../_shared/tiktokContentAccountProfile.ts";

function redirectToAppPath(path: string, query: string, status = 302): Response {
  const origin = appPublicOrigin() || "http://localhost:5173";
  const normalizedPath = path.startsWith("/") ? path : `/${path}`;
  return new Response(null, {
    status,
    headers: { Location: `${origin}${normalizedPath}${query}` },
  });
}

function resolveOAuthReturnPath(stored: string | null | undefined): string {
  const path = String(stored ?? "").trim();
  if (path && TIKTOK_CONTENT_OAUTH_RETURN_PATHS.has(path)) return path;
  return "/digital-marketing/social-media-performance/tiktok/settings";
}

function sanitizeOAuthError(msg: string): string {
  const trimmed = msg.trim();
  if (!trimmed || trimmed === "OK" || trimmed === "ok") return "token_exchange_failed";
  return trimmed;
}

type OAuthStateRow = {
  id: string;
  organization_id: string;
  user_id: string;
  expires_at: string;
  return_path?: string | null;
  oauth_purpose?: string | null;
  target_open_id?: string | null;
};

Deno.serve(async (req: Request) => {
  const url = new URL(req.url);
  const authCode = url.searchParams.get("auth_code")?.trim() ??
    url.searchParams.get("code")?.trim() ?? "";
  const state = url.searchParams.get("state")?.trim() ?? "";
  const oauthError = url.searchParams.get("error")?.trim() ?? "";

  const redirectDefault = (query: string, returnPath?: string | null) =>
    redirectToAppPath(resolveOAuthReturnPath(returnPath), query);

  if (oauthError) {
    return redirectDefault(`?oauth_error=${encodeURIComponent(oauthError)}`);
  }
  if (!authCode || !state) {
    return redirectDefault("?oauth_error=missing_code_or_state");
  }

  const businessOAuth = readPlatformTikTokContentOAuth();
  const publishOAuth = readPlatformTikTokContentPublishOAuth();
  if (!businessOAuth && !publishOAuth) {
    return redirectDefault("?oauth_error=oauth_not_configured");
  }

  const redirectUri = tiktokContentOAuthRedirectUri();
  const tokenKind = TIKTOK_CONTENT_OAUTH_TOKEN_KINDS.ttUser;

  const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";
  if (!supabaseUrl || !serviceRoleKey) {
    return redirectDefault("?oauth_error=server_misconfigured");
  }

  const admin = createClient(supabaseUrl, serviceRoleKey);

  const { data: stateRowEarly } = await admin
    .from("tiktok_content_oauth_states")
    .select("id, organization_id, user_id, expires_at, return_path, oauth_purpose, target_open_id")
    .eq("state_token", state)
    .maybeSingle();

  const oauthReturnPathEarly = resolveOAuthReturnPath(
    stateRowEarly?.return_path != null ? String(stateRowEarly.return_path) : null,
  );

  if (String(stateRowEarly?.oauth_purpose ?? "full") === "publish") {
    if (!stateRowEarly?.id) {
      return redirectDefault("?oauth_error=invalid_state", oauthReturnPathEarly);
    }
    const expiresAtPublish = new Date(String(stateRowEarly.expires_at)).getTime();
    if (!Number.isFinite(expiresAtPublish) || expiresAtPublish < Date.now()) {
      await admin.from("tiktok_content_oauth_states").delete().eq("id", stateRowEarly.id);
      return redirectDefault("?oauth_error=state_expired", oauthReturnPathEarly);
    }

    if (!publishOAuth) {
      return redirectDefault("?oauth_error=publish_oauth_not_configured", oauthReturnPathEarly);
    }

    let loginKitData;
    try {
      loginKitData = await exchangeTikTokContentAuthCode(
        publishOAuth.clientKey,
        publishOAuth.clientSecret,
        authCode,
        redirectUri,
      );
    } catch (e) {
      const msg = sanitizeOAuthError(e instanceof Error ? e.message : "token_exchange_failed");
      console.error("tiktok-content-oauth-callback publish-only:", msg);
      return redirectDefault(`?oauth_error=${encodeURIComponent(msg)}`, oauthReturnPathEarly);
    }

    await admin.from("tiktok_content_oauth_states").delete().eq("id", stateRowEarly.id);

    const organizationId = String(stateRowEarly.organization_id);
    const targetOpenId = String(stateRowEarly.target_open_id ?? loginKitData.open_id).trim();
    const now = new Date().toISOString();

    try {
      const publishAccessEnc = await encryptTikTokContentToken(loginKitData.access_token);
      const publishRefreshEnc = await encryptTikTokContentToken(loginKitData.refresh_token);
      const publishAccessExpires = loginKitData.expires_in
        ? new Date(Date.now() + loginKitData.expires_in * 1000).toISOString()
        : null;
      const publishOAuthScopes = mergeTikTokContentOAuthScopes(
        loginKitData.scope,
        TIKTOK_CONTENT_PUBLISH_OAUTH_SCOPES,
      );

      const { error: publishTokErr } = await admin
        .from("organization_tiktok_content_connection_tokens")
        .update({
          publish_access_token_enc: publishAccessEnc,
          publish_refresh_token_enc: publishRefreshEnc,
          publish_access_token_expires_at: publishAccessExpires,
          publish_oauth_scopes: publishOAuthScopes,
          updated_at: now,
        })
        .eq("organization_id", organizationId)
        .eq("open_id", targetOpenId);

      if (publishTokErr) {
        console.error("tiktok-content-oauth-callback publish-only update:", publishTokErr.message);
        return redirectDefault("?oauth_error=save_token_failed", oauthReturnPathEarly);
      }
    } catch (e) {
      console.error("tiktok-content-oauth-callback publish-only encrypt:", e);
      return redirectDefault("?oauth_error=encryption_failed", oauthReturnPathEarly);
    }

    return redirectDefault("?connected=1&publish=1", oauthReturnPathEarly);
  }

  // Business tt_user: comments + insights (business-api Content Insight app).
  if (!businessOAuth) {
    return redirectDefault("?oauth_error=oauth_not_configured");
  }

  const [stateRes, businessResult] = await Promise.all([
    admin
      .from("tiktok_content_oauth_states")
      .select("id, organization_id, user_id, expires_at, return_path, oauth_purpose, target_open_id")
      .eq("state_token", state)
      .maybeSingle(),
    exchangeTikTokBusinessOrganicAuthCode(
      businessOAuth.clientKey,
      businessOAuth.clientSecret,
      authCode,
      redirectUri,
    ).then(
      (data) => ({ ok: true as const, data }),
      (e) => ({ ok: false as const, error: e }),
    ),
  ]);

  const tokenResult = businessResult;

  const stateRow = stateRes.data as OAuthStateRow | null;
  const oauthReturnPath = resolveOAuthReturnPath(
    stateRow?.return_path != null ? String(stateRow.return_path) : null,
  );

  if (!tokenResult.ok) {
    const err = tokenResult as { ok: false; error: unknown };
    const msg = sanitizeOAuthError(
      err.error instanceof Error ? err.error.message : "token_exchange_failed",
    );
    console.error("tiktok-content-oauth-callback:", msg);
    return redirectDefault(`?oauth_error=${encodeURIComponent(msg)}`, oauthReturnPath);
  }

  const tokenData = tokenResult.data;

  if (stateRes.error || !stateRow?.id) {
    return redirectDefault("?oauth_error=invalid_state", oauthReturnPath);
  }

  const expiresAt = new Date(String(stateRow.expires_at)).getTime();
  if (!Number.isFinite(expiresAt) || expiresAt < Date.now()) {
    await admin.from("tiktok_content_oauth_states").delete().eq("id", stateRow.id);
    return redirectDefault("?oauth_error=state_expired", oauthReturnPath);
  }

  await admin.from("tiktok_content_oauth_states").delete().eq("id", stateRow.id);

  const organizationId = String(stateRow.organization_id);
  const openId = tokenData.open_id;

  let accessEnc: string;
  let refreshEnc: string;
  try {
    accessEnc = await encryptTikTokContentToken(tokenData.access_token);
    refreshEnc = await encryptTikTokContentToken(tokenData.refresh_token);
  } catch (e) {
    console.error("tiktok-content-oauth-callback encrypt:", e);
    return redirectDefault("?oauth_error=encryption_failed", oauthReturnPath);
  }

  const now = new Date().toISOString();
  const accessExpires = tokenData.expires_in
    ? new Date(Date.now() + tokenData.expires_in * 1000).toISOString()
    : null;
  const refreshExpires = tokenData.refresh_expires_in
    ? new Date(Date.now() + tokenData.refresh_expires_in * 1000).toISOString()
    : null;

  let displayName = "";
  let avatarUrl: string | null = null;
  try {
    const userInfo = await fetchTikTokUserInfo(tokenData.access_token);
    displayName = userInfo.display_name?.trim() ?? "";
    avatarUrl = userInfo.avatar_url?.trim() || null;
  } catch (e) {
    console.warn(
      "tiktok-content-oauth-callback userInfo:",
      e instanceof Error ? e.message : e,
    );
  }
  if (!displayName || isPlaceholderTikTokAccountLabel(displayName, openId)) {
    displayName = `TikTok ${openId.slice(0, 8)}`;
  }

  const { error: connErr } = await admin.from("organization_tiktok_content_connections").upsert(
    {
      organization_id: organizationId,
      oauth_connected_at: now,
      is_active: true,
      updated_at: now,
      created_by: stateRow.user_id,
    },
    { onConflict: "organization_id" },
  );
  if (connErr) {
    console.error("tiktok-content-oauth-callback connection:", connErr.message);
    return redirectDefault("?oauth_error=save_connection_failed", oauthReturnPath);
  }

  let publishAccessEnc: string | null = null;
  let publishRefreshEnc: string | null = null;
  let publishAccessExpires: string | null = null;
  let publishOAuthScopes: string | null = null;

  const { error: tokErr } = await admin.from("organization_tiktok_content_connection_tokens").upsert(
    {
      organization_id: organizationId,
      open_id: openId,
      access_token_enc: accessEnc,
      refresh_token_enc: refreshEnc,
      access_token_expires_at: accessExpires,
      refresh_token_expires_at: refreshExpires,
      oauth_scopes: mergeTikTokContentOAuthScopes(tokenData.scope, TIKTOK_CONTENT_OAUTH_SCOPES),
      oauth_token_kind: tokenKind,
      ...(publishAccessEnc
        ? {
          publish_access_token_enc: publishAccessEnc,
          publish_refresh_token_enc: publishRefreshEnc,
          publish_access_token_expires_at: publishAccessExpires,
          publish_oauth_scopes: publishOAuthScopes,
        }
        : {}),
      updated_at: now,
    },
    { onConflict: "organization_id,open_id" },
  );
  if (tokErr) {
    console.error("tiktok-content-oauth-callback token:", tokErr.message);
    return redirectDefault("?oauth_error=save_token_failed", oauthReturnPath);
  }

  const { data: existingAccounts } = await admin
    .from("organization_tiktok_content_accounts")
    .select("id, is_default, open_id")
    .eq("organization_id", organizationId)
    .eq("is_active", true);

  const hasDefault = (existingAccounts ?? []).some(
    (a) => Boolean((a as { is_default?: boolean }).is_default),
  );
  const existingOpenId = (existingAccounts ?? []).find(
    (a) => String((a as { open_id?: string }).open_id) === openId,
  );
  const isExistingAccount = Boolean(existingOpenId);

  const { error: accErr } = await admin.from("organization_tiktok_content_accounts").upsert(
    {
      organization_id: organizationId,
      open_id: openId,
      label: displayName,
      display_name: displayName,
      avatar_url: avatarUrl,
      is_default: existingOpenId
        ? Boolean((existingOpenId as { is_default?: boolean }).is_default)
        : !hasDefault,
      is_active: true,
      updated_at: now,
    },
    { onConflict: "organization_id,open_id" },
  );
  if (accErr) {
    console.error("tiktok-content-oauth-callback account:", accErr.message);
    return redirectDefault("?oauth_error=save_account_failed", oauthReturnPath);
  }

  const query = isExistingAccount ? "?connected=1&existing=1" : "?connected=1";
  return redirectDefault(query, oauthReturnPath);
});

/**
 * AES-256-GCM for TikTok Content OAuth tokens.
 * Reuses TIKTOK_ADS_CONFIG_ENCRYPTION_KEY (or TIKTOK_CONTENT_CONFIG_ENCRYPTION_KEY).
 */

const ALGO = "AES-GCM";
const IV_LEN = 12;
const TAG_LEN = 128;

function decodeKey(raw: string): Uint8Array {
  const trimmed = raw.trim();
  if (!trimmed) throw new Error("Encryption key is not set");
  if (/^[0-9a-fA-F]{64}$/.test(trimmed)) {
    const bytes = new Uint8Array(32);
    for (let i = 0; i < 32; i++) {
      bytes[i] = parseInt(trimmed.slice(i * 2, i * 2 + 2), 16);
    }
    return bytes;
  }
  const bin = atob(trimmed);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  if (bytes.length !== 32) {
    throw new Error("Encryption key must be 32 bytes (base64 or 64-char hex)");
  }
  return bytes;
}

function getKeyBytes(): Uint8Array {
  const raw = Deno.env.get("TIKTOK_CONTENT_CONFIG_ENCRYPTION_KEY")?.trim() ??
    Deno.env.get("TIKTOK_ADS_CONFIG_ENCRYPTION_KEY") ?? "";
  return decodeKey(raw);
}

function toBase64(bytes: Uint8Array): string {
  let s = "";
  for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
  return btoa(s);
}

function fromBase64(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

async function encrypt(plaintext: string): Promise<string> {
  const keyBytes = getKeyBytes();
  const iv = crypto.getRandomValues(new Uint8Array(IV_LEN));
  const key = await crypto.subtle.importKey("raw", keyBytes, { name: ALGO }, false, ["encrypt"]);
  const enc = await crypto.subtle.encrypt(
    { name: ALGO, iv, tagLength: TAG_LEN },
    key,
    new TextEncoder().encode(plaintext),
  );
  const combined = new Uint8Array(iv.length + enc.byteLength);
  combined.set(iv, 0);
  combined.set(new Uint8Array(enc), iv.length);
  return toBase64(combined);
}

async function decrypt(ciphertextB64: string): Promise<string> {
  const keyBytes = getKeyBytes();
  const combined = fromBase64(ciphertextB64.trim());
  if (combined.length < IV_LEN + 16) throw new Error("Invalid encrypted token payload");
  const iv = combined.slice(0, IV_LEN);
  const data = combined.slice(IV_LEN);
  const key = await crypto.subtle.importKey("raw", keyBytes, { name: ALGO }, false, ["decrypt"]);
  const dec = await crypto.subtle.decrypt({ name: ALGO, iv, tagLength: TAG_LEN }, key, data);
  return new TextDecoder().decode(dec);
}

export async function encryptTikTokContentToken(plaintext: string): Promise<string> {
  return encrypt(plaintext);
}

export async function decryptTikTokContentToken(ciphertextB64: string): Promise<string> {
  return decrypt(ciphertextB64);
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";

export const tiktokContentCorsHeaders: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Max-Age": "86400",
};

export const TIKTOK_CONTENT_API_BASE = "https://open.tiktokapis.com/v2";
export const TIKTOK_BUSINESS_API_BASE = "https://business-api.tiktok.com/open_api/v1.3";
export const TIKTOK_CONTENT_OAUTH_SCOPES =
  "user.info.basic,video.list,user.info.stats,comment.list,comment.list.manage,video.upload,video.publish";

export const TIKTOK_CONTENT_PUBLISH_SCOPES = ["video.upload", "video.publish"] as const;

/** Login Kit / Direct Post (developers.tiktok.com) — separate from business-api CONTENT credentials. */
export const TIKTOK_CONTENT_PUBLISH_OAUTH_SCOPES =
  "user.info.basic,video.upload,video.publish";

export type TikTokContentOAuthTokenKind = "login_kit" | "tt_user";

export const TIKTOK_CONTENT_OAUTH_TOKEN_KINDS = {
  loginKit: "login_kit" as TikTokContentOAuthTokenKind,
  ttUser: "tt_user" as TikTokContentOAuthTokenKind,
};

export const TIKTOK_CONTENT_COMMENT_SCOPES = ["comment.list", "comment.list.manage"] as const;

/** Union comma-separated OAuth scope strings (deduped, stable order). */
export function mergeTikTokContentOAuthScopes(
  ...scopeStrings: (string | null | undefined)[]
): string {
  const merged = new Set<string>();
  for (const raw of scopeStrings) {
    for (const part of String(raw ?? "").split(",")) {
      const trimmed = part.trim();
      if (trimmed) merged.add(trimmed);
    }
  }
  return [...merged].join(",");
}

/** TikTok often omits scopes in token JSON; merge stored + requested scopes. */
export function resolveTikTokContentOAuthScopes(stored: string | null | undefined): string {
  return mergeTikTokContentOAuthScopes(stored, TIKTOK_CONTENT_OAUTH_SCOPES);
}

export function tiktokContentScopesIncludeComments(scope: string | null | undefined): boolean {
  const parts = String(scope ?? "")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
  return TIKTOK_CONTENT_COMMENT_SCOPES.every((required) => parts.includes(required));
}

export function tiktokContentScopesIncludePublish(scope: string | null | undefined): boolean {
  const parts = String(scope ?? "")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
  return TIKTOK_CONTENT_PUBLISH_SCOPES.every((required) => parts.includes(required));
}

export function tiktokContentJson(body: object, status: number): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...tiktokContentCorsHeaders, "Content-Type": "application/json" },
  });
}

export function readPlatformTikTokContentOAuth(): { clientKey: string; clientSecret: string } | null {
  const clientKey = Deno.env.get("TIKTOK_CONTENT_CLIENT_KEY")?.trim() ??
    Deno.env.get("TIKTOK_CONTENT_APP_ID")?.trim() ?? "";
  const clientSecret = Deno.env.get("TIKTOK_CONTENT_CLIENT_SECRET")?.trim() ??
    Deno.env.get("TIKTOK_CONTENT_APP_SECRET")?.trim() ?? "";
  if (!clientKey || !clientSecret) return null;
  return { clientKey, clientSecret };
}

/** developers.tiktok.com app — Login Kit token exchange & publish OAuth start. */
export function readPlatformTikTokContentPublishOAuth(): { clientKey: string; clientSecret: string } | null {
  const clientKey = Deno.env.get("TIKTOK_CONTENT_PUBLISH_CLIENT_KEY")?.trim() ??
    Deno.env.get("TIKTOK_DEVELOPERS_CLIENT_KEY")?.trim() ?? "";
  const clientSecret = Deno.env.get("TIKTOK_CONTENT_PUBLISH_CLIENT_SECRET")?.trim() ??
    Deno.env.get("TIKTOK_DEVELOPERS_CLIENT_SECRET")?.trim() ?? "";
  if (!clientKey || !clientSecret) return null;
  return { clientKey, clientSecret };
}

export function isTikTokContentPlatformConfigured(): boolean {
  return readPlatformTikTokContentOAuth() !== null;
}

export function isTikTokContentPublishPlatformConfigured(): boolean {
  return readPlatformTikTokContentPublishOAuth() !== null;
}

export function requireTikTokContentPlatformConfigured(): Response | null {
  if (!isTikTokContentPlatformConfigured()) {
    return tiktokContentJson(
      {
        error:
          "TikTok Content is not configured. Set TIKTOK_CONTENT_CLIENT_KEY and TIKTOK_CONTENT_CLIENT_SECRET in Supabase Edge Function secrets.",
      },
      503,
    );
  }
  return null;
}

export function requireTikTokContentPublishPlatformConfigured(): Response | null {
  if (!isTikTokContentPublishPlatformConfigured()) {
    return tiktokContentJson(
      {
        error:
          "TikTok publish is not configured. Set TIKTOK_CONTENT_PUBLISH_CLIENT_KEY and TIKTOK_CONTENT_PUBLISH_CLIENT_SECRET (developers.tiktok.com app) in Supabase Edge Function secrets.",
      },
      503,
    );
  }
  return null;
}

export function tiktokContentOAuthRedirectUri(): string {
  const explicit = Deno.env.get("TIKTOK_CONTENT_OAUTH_REDIRECT_URI")?.trim();
  if (explicit) return explicit;
  const supabaseUrl = (Deno.env.get("SUPABASE_URL") ?? "").replace(/\/+$/, "");
  return `${supabaseUrl}/functions/v1/tiktok-content-oauth-callback`;
}

export function appPublicOrigin(): string {
  const raw =
    Deno.env.get("APP_PUBLIC_URL")?.trim() ??
    Deno.env.get("SYNCKERJA_APP_URL")?.trim() ??
    "";
  return raw.replace(/\/+$/, "");
}

export const TIKTOK_CONTENT_OAUTH_RETURN_PATHS = new Set([
  "/digital-marketing/social-media-performance/tiktok/settings",
  "/digital-marketing/social-media-performance/manage-comments/tiktok/settings",
]);

export async function getUserFromBearer(
  admin: SupabaseClient,
  authHeader: string | null,
): Promise<{ userId: string } | { error: Response }> {
  const token = authHeader?.startsWith("Bearer ") ? authHeader.slice("Bearer ".length).trim() : "";
  if (!token) return { error: tiktokContentJson({ error: "Unauthorized" }, 401) };
  const { data: userRes, error: userErr } = await admin.auth.getUser(token);
  if (userErr || !userRes?.user?.id) {
    return { error: tiktokContentJson({ error: "Invalid token" }, 401) };
  }
  return { userId: userRes.user.id };
}

export async function isOmnichannelContentAdmin(
  admin: SupabaseClient,
  userId: string,
  organizationId: string,
): Promise<boolean> {
  const { data: owner } = await admin
    .from("user_roles")
    .select("id")
    .eq("user_id", userId)
    .eq("organization_id", organizationId)
    .eq("role", "owner")
    .maybeSingle();
  if (owner) return true;

  const { data: staffRows } = await admin
    .from("organization_omnichannel_staff")
    .select("employee_id, employees!inner(user_id)")
    .eq("organization_id", organizationId)
    .eq("role", "admin");

  for (const row of staffRows ?? []) {
    const emp = row as { employees?: { user_id?: string } | { user_id?: string }[] };
    const employees = emp.employees;
    const userIds: string[] = [];
    if (Array.isArray(employees)) {
      for (const e of employees) {
        if (e?.user_id) userIds.push(String(e.user_id));
      }
    } else if (employees && typeof employees === "object" && "user_id" in employees) {
      const uid = (employees as { user_id?: string }).user_id;
      if (uid) userIds.push(String(uid));
    }
    if (userIds.includes(userId)) return true;
  }
  return false;
}

export async function requireOrgAdmin(
  admin: SupabaseClient,
  userId: string,
  organizationId: string,
): Promise<Response | null> {
  const ok = await isOmnichannelContentAdmin(admin, userId, organizationId);
  if (!ok) return tiktokContentJson({ error: "Forbidden" }, 403);
  return null;
}

export async function requireActiveOrg(
  admin: SupabaseClient,
  userId: string,
  organizationId: string,
): Promise<Response | null> {
  const { data: profile } = await admin
    .from("profiles")
    .select("active_organization_id")
    .eq("user_id", userId)
    .maybeSingle();
  const activeOrg = profile?.active_organization_id != null ? String(profile.active_organization_id) : "";
  if (!activeOrg || activeOrg !== organizationId) {
    return tiktokContentJson({ error: "Forbidden" }, 403);
  }
  return null;
}

import {
  TIKTOK_BUSINESS_API_BASE,
  TIKTOK_CONTENT_API_BASE,
